526	// Deliver the converge as one commit on a FRESH per-cycle maintenance branch,
527	// native git: dispose of the family's open PR first (merge it if last cycle's
528	// content is verified, otherwise close it), then cut a new dated branch + PR and
529	// arm auto-merge when the member asked for it.
530	//
531	// Nothing is reused. A maintenance PR is one cycle's deterministic converge, and
532	// a cycle that did not land has nothing to hand the next one — inheriting it is
533	// what turned a single failed arm into a PR that outlived every subsequent cycle
534	// (#455/#205/#95). The disposal happens BEFORE the converge is pushed, because
535	// the push would replace the head sha the merge evidence hangs on.
536	async function deliver(root, repo, base, token, delivery, seed, withheld = []) {
537	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
538	  const openPr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
539	  let pr = null;
540	  let merged = false;
541	
542	  if (openPr?.number) {
543	    // `wait` is the one case that keeps the PR: its checks are still running and
544	    // may yet land it. Skip this cycle entirely rather than race them — the
545	    // converge is idempotent, so tomorrow simply does it again.
546	    const kept = await disposeOpenPull(token, repo, openPr, delivery)
547	      .catch((e) => { console.log(`baselining: disposing of PR #${openPr.number} failed: ${e.message}`); return openPr; });
548	    if (kept) {
549	      console.log(`baselining: PR #${openPr.number} still stands — leaving this cycle's converge undelivered`);
550	      // Same shape as the delivery path below — the caller reads `.branch`/`.pr`
551	      // unconditionally, and the bare-ref return this used to make crashed it.
552	      return { branch: kept.head?.ref ?? null, pr: kept.number ?? openPr.number, merged: false };
553	    }
554	  }
