558	  git(['-C', root, 'checkout', '-B', branch]);
559	  git(['-C', root, 'add', '-A']);
560	  // Withhold what this token cannot push (see withheldWorkflowPaths). Unstaged, not
561	  // reverted: the file stays in the working tree so nothing here has to reason about
