585	  if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
586	  pr = created.json;
587	
588	  // ARM GitHub's native auto-merge (not an immediate merge): the PR lands
589	  // automatically once this repo's required checks pass, and the run never blocks
590	  // on CI. Auto-merge is a GraphQL-only mutation.
591	  //
592	  // Every cycle opens its own PR and arms it, so the arm is never stale — and it
593	  // is no longer the only thing standing between a converge and `main`: the arm
594	  // failing (auto-merge off, or a gated pull_request run) now costs one cycle,
595	  // not forever, because the next cycle merges this PR on its concluded runs
596	  // (pullDisposition) or closes it and re-cuts. Idempotent either way.
597	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open above emitted no
598	  // pull_request event, so without this the PR has no runs (#565, the
599	  // ciDispatchPlan block). AFTER the push, so the dispatched runs execute the
600	  // branch's own head; every delivering cycle, since a force-push emits no
601	  // synchronize event either and each new head needs its own runs. Best-effort:
602	  // a dispatch failure must not fail the converge that was already pushed.
603	  //
604	  // It runs BEFORE the delivery decision because it is what establishes whether
605	  // this repo has any PR CI at all — the fact deliveryAction turns on.
606	  const ci = await dispatchCiRuns(token, repo, branch)
607	    .catch((e) => { console.log(`baselining: CI dispatch on ${branch} failed: ${e.message}`); return null; });
608	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
609	
610	  if (pr?.number) {
611	    const action = deliveryAction({ delivery, hasPrCi });
612	    if (action === 'merge') {
613	      const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
614	        method: 'PUT', body: { merge_method: 'squash' },
615	      });
616	      if (res.status === 200) { merged = true; console.log(`baselining: merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
