677	// The I/O half of the disposal: read the workflow runs for the open PR's head
678	// sha, decide with pullDisposition, and either merge it (last cycle's content is
679	// verified — the arm just never landed it) or close it and delete its branch so
680	// this cycle re-cuts from scratch. Returns the PR when it still stands (a `wait`,
681	// a `review` member, or a failed attempt), null when the way is clear.
682	//
683	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it
684	// found it, and the cycle skips rather than piling a second PR on top.
685	async function disposeOpenPull(token, repo, pr, delivery) {
686	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha}&per_page=100`);
687	  if (status !== 200) {
688	    console.log(`baselining: could not read the runs for PR #${pr.number}'s head (HTTP ${status})`);
689	    return pr;
690	  }
691	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
692	  const disposition = pullDisposition({ delivery, runs });
693	
694	  if (disposition === 'keep' || disposition === 'wait') {
695	    console.log(`baselining: keeping PR #${pr.number} (${disposition})`);
696	    return pr;
697	  }
698	
699	  if (disposition === 'merge') {
700	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
701	      method: 'PUT', body: { merge_method: 'squash' },
702	    });
703	    if (res.status === 200) {
704	      console.log(`baselining: merged PR #${pr.number} — ${mergeReason(runs)}`);
705	      await deleteBranch(token, repo, pr.head?.ref);
706	      return null;
707	    }
708	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
709	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
710	  }
711	
712	  // Closed, not left to rot: whatever went wrong on that head, the next converge
713	  // reproduces the same content from the same inputs. Named in the log because a
714	  // member closing its maintenance PR every single night is a repo whose CI needs
715	  // a human, and the pattern has to be visible to be noticed.
716	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
717	  if (closed.status !== 200) {
718	    console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
719	    return pr;
720	  }
721	  console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
722	  await deleteBranch(token, repo, pr.head?.ref);
723	  return null;
724	}
