726	// Tidy the ref behind a disposed PR — a closed branch left on the remote is litter
727	// that accumulates one per cycle. Never fatal: the branch is not the deliverable.
728	async function deleteBranch(token, repo, ref) {
729	  if (!ref) return;
730	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
731	  if (res.status !== 204) console.log(`baselining: could not delete branch ${ref} (HTTP ${res.status})`);
732	}
