767	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
768	// but the repo has not configured. The wiring converge stamps every declared name
769	// into the scheduler workflow, so by the time this runs the value is either in the
770	// environment or genuinely unset — no separate probe needed.
771	//
772	// This is the adoption interview's posture, not a gate: nothing fails, no check
773	// fires, and the task that needs the secret simply doesn't work until someone adds
774	// it. One open issue per repo (matched by exact title) so an unconfigured secret
775	// costs one issue, not one per night. Exported for the tests.
776	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
777	
778	export function unconfiguredSecrets(declared, env) {
779	  return (declared ?? []).filter((name) => !env[name]);
780	}
781	
782	async function askForSecrets(token, repo, names) {
783	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
784	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
785	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
786	  const body = [
787	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
788	    'Until it is, that task cannot do its work — everything else keeps running normally.',
789	    '',
790	    ...names.map((n) => `- \`${n}\``),
791	    '',
792	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
793	  ].join('\n');
794	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
