107	// Ensure the required settings hooks are present (add-if-missing, never clobber).
108	// Returns { added: [labels], error? }. A malformed settings file is reported, never
109	// overwritten (the transactional stance — surface it, don't destroy hand config).
110	export function ensureHooks(root) {
111	  const path = join(root, SETTINGS_PATH);
112	  let settings = {};
113	  if (existsSync(path)) {
114	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
115	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
116	  }
