206	// exists, otherwise introducing it just under the title (a README's badges belong
207	// where a reader looks first) or at the very top when there is no heading.
208	// Returns true when the file was written. No README, or nothing to show, means
209	// nothing to do — this converge never creates a README.
210	export function convergeBadgeRow(root, entries) {
211	  const path = join(root, README);
212	  if (!existsSync(path) || !entries.length) return false;
213	  const text = readFileSync(path, 'utf8');
214	  const row = renderBadgeRow(entries);
215	  if (BADGE_ROW_RE.test(text)) {
216	    const next = text.replace(BADGE_ROW_RE, row);
217	    if (next === text) return false;
218	    writeFileSync(path, next);
219	    return true;
220	  }
221	  const lines = text.split('\n');
222	  const title = lines.findIndex((l) => l.startsWith('# '));
223	  const at = title === -1 ? 0 : title + 1;
224	  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
225	  writeFileSync(path, lines.join('\n'));
226	  return true;
227	}
228	
229	// Converge every wiring surface, returning a flat summary of what changed (empty
230	// when the repo was already converged). `stubText` is the vendored scheduler stub.
231	//
232	// `badges` defaults off, and that default is the point: the nightly takes this
233	// call as it stands and only bootstrap opts the README row in.
234	export async function convergeWiring(root, fullName, stubText, secretNames = [], { badges = false } = {}) {
235	  const changed = [];
236	  if (convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
237	  const hooks = ensureHooks(root);
238	  for (const h of hooks.added) changed.push(`hook:${h}`);
239	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
240	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
241	  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
242	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
243	}
244	
245	// CLI: `node converge-wiring.mjs [owner/repo] [--badges]` — converge THIS repo's
246	// wiring. The full name comes from argv or GITHUB_REPOSITORY/CLAUDINITE_REPO; the
247	// scheduler stub from the vendored mount. This is the single surface bootstrap
248	// (Part 6) and baselining both invoke, so the wiring set is defined once, here —
249	// with `--badges` the one thing that differs between them: bootstrap passes it to
250	// seed the README pack row, the nightly leaves the README alone.
251	async function main() {
252	  const argv = process.argv.slice(2);
253	  const badges = argv.includes('--badges');
254	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
255	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
256	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
257	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
258	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
259	  const secretNames = await declaredSecrets(root, await repoConfig(root));
260	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges });
261	  if (error) console.log(`! ${error}`);
262	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
263	}
264	
265	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
266

